#include <string>
#include <sstream>

using namespace std;

class Solution {
public:
    string toGoatLatin(string sentence) {
        istringstream iss(sentence);
        string word, res, suffix = "a";
        while (iss >> word) {
            char first = word[0];
            if (string("aeiouAEIOU").find(first) != string::npos)
                word += "ma";
            else
                word = word.substr(1) + first + "ma";
            word += suffix;
            suffix += "a";
            if (!res.empty()) res += " ";
            res += word;
        }
        return res;
    }
};
